# self-verify each file exactly by id list
ids = ["MP-017","MP-018","MP-019"] + [f"OC-{i:03d}" for i in range(1,18)]
ok = 0
for cid in ids:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        j = json.load(f)
    assert j["case_id"] == cid and j["prediction_text"] and j["basis"] and 0 <= j["confidence"] <= 1
    assert set(j["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
